                  </TouchableOpacity>
                );
              })}
            </ScrollView>
          </View>

          {/* Section 2: Condition */}
          <View style={styles.section}>
            <Text style={styles.sectionTitle}>CONDITION</Text>
            <View style={styles.pillRow}>
              {CONDITION_OPTIONS.map(option => {
                const isSelected = draft.condition === option.value;
